// app.module.ts
import { NgModule, APP_INITIALIZER } from '@angular/core';
import { BrowserModule } from '@angular/platform-browser';
import { ReactiveFormsModule, FormsModule } from '@angular/forms';
import { HttpClientModule } from '@angular/common/http';
import { RouterModule } from '@angular/router';
import { KeycloakAngularModule, KeycloakService } from 'keycloak-angular';

import { AppComponent } from './app.component';
import { RegistrationComponent } from './components/registration/registration.component';
import { EntranceComponent } from './components/entrance/entrance.component';
import { LoginComponent } from './components/login/login.component';
import { DashboardComponent } from './components/dashboard/dashboard.component';

import { routes } from './app.routes';

// Функция для инициализации Keycloak
let keycloakInitialized = false; // Флаг для отслеживания состояния

function initializeKeycloak(keycloak: KeycloakService) {
  return () => {
    if (keycloakInitialized) {
      return Promise.resolve(); // Уже инициализирован
    }

    return keycloak.init({
      config: {
        url: 'http://localhost:8080',
        realm: 'my-app',
        clientId: 'angular-app'
      },
      initOptions: {
        onLoad: 'check-sso',
        checkLoginIframe: false
      }
    }).then((authenticated) => {
      keycloakInitialized = true; // Устанавливаем флаг после успеха
      console.log('Keycloak инициализирован', authenticated);
    }).catch(error => {
      console.error('Детали ошибки инициализации Keycloak:', error);
    });
  };
}

@NgModule({
  declarations: [
    AppComponent,
    RegistrationComponent,
    EntranceComponent,
    LoginComponent,
    DashboardComponent
  ],
  imports: [
    BrowserModule,
    ReactiveFormsModule,
    FormsModule,
    HttpClientModule,
    RouterModule.forRoot(routes),
    KeycloakAngularModule
  ],
  providers: [
    {
      provide: APP_INITIALIZER,
      useFactory: initializeKeycloak,
      multi: true,
      deps: [KeycloakService]
    }
  ],
  bootstrap: [AppComponent]
})
export class AppModule { }
